import { ActionOrTriggerListTypeEnum, IActionOrTriggerListPageParams } from "@app/static"
import { getTriggerOrActionListPageParams, ProjectMemberType, projectEventUtils } from "@droid/project-v2-interface"
import { actionShowFloatWindowUtils } from "@droid/project-v2-ext"
import { throwTraceError, Log, isDev } from "@fanfanlo"
import { createActionOrTriggerButtonRender, IActionOrTriggerItem } from "../../../../../trigger-list-action-list-common/ITriggerList-IActionList-common.intf"
import { ulid } from "ulid"

const fileLog = new Log(false, 'accessibility_node_reader_action')
// fileLog.pause = true
// fileLog.childrenPaused = true

export const accessibilityNodeReaderActionItem: IActionOrTriggerItem = {
    id: "accessibility-node-reader-action-item-anr001",
    i18nNs: "homepage/components/page/action-list/groups/float-window/accessibility-node-reader/content",
    nameKey: "content.name",
    group: "accessibilityNodeReaderActionItem.group",
    descriptionKey: "content.description",
    type: "action",
    LinkRender: createActionOrTriggerButtonRender(onSelect)
}

// 参数接口定义
interface INodeClickDetectorParams {
    closeAfterConfirm?: boolean
    hideAfterConfirm?: boolean
    opts: {
        requirePn: boolean
        requireAn: boolean
        requireCn: boolean
        nodeRequiredFields: string[]
        allowEmptyNode: boolean
        dispatchEventAfterConfirm: boolean
        dispatchEventName: string | null
        dispatchEventData: {
            projectId: string
            action: string
        }
    }
}

function getNodeReaderUrl(projectUlid: string): string {
    const fnLog = fileLog.sub(false, 'getNodeReaderUrl_fn')
    fnLog.log('开始获取URL')
    fnLog.log('isDev:', isDev)
    fnLog.log('projectUlid:', projectUlid)

    // 生成一个新的ulid作为jumpProjectUlid
    // 注意: 这种生成方式导致这个action被写死只能做跳一跳功能的工具
    // 因为每次都生成新的ulid，而不是使用实际的目标项目ID
    const jumpProjectUlid = ulid()
    fnLog.log('生成jumpProjectUlid:', jumpProjectUlid)

    // 构建参数对象
    const params: INodeClickDetectorParams = {
        closeAfterConfirm: false,
        hideAfterConfirm: false,
        opts: {
            requirePn: true,
            requireAn: true,
            requireCn: false,
            nodeRequiredFields: [],
            allowEmptyNode: false,
            dispatchEventAfterConfirm: true,
            dispatchEventName: null,
            dispatchEventData: {
                projectId: jumpProjectUlid,
                action: 'addNodeClick'
            }
        }
    }
    fnLog.log('构建params:', JSON.stringify(params))

    // 将参数序列化并编码为base64
    const paramsJson = JSON.stringify(params)
    fnLog.log('paramsJson:', paramsJson)

    const paramsBase64 = btoa(paramsJson)
    fnLog.log('paramsBase64:', paramsBase64)

    if (isDev) {
        const url = `https://192.168.177.180:19016/pages/accessibility-node-click-detector/#${paramsBase64}`
        fnLog.log('dev环境, url:', url)
        return url
    }

    if (typeof window === 'undefined') {
        fnLog.log('服务端渲染, 返回空字符串')
        return ''
    }

    const currentDomain = window.location.origin
    const url = `${currentDomain}/pages/accessibility-node-click-detector/#${paramsBase64}`
    fnLog.log('非dev环境, currentDomain:', currentDomain)
    fnLog.log('url:', url)
    return url
}

function onSelect({ query, item }: { query: IActionOrTriggerListPageParams, item: IActionOrTriggerItem }) {
    const fnLog = fileLog.sub(false, 'onSelect_fn')
    // fnLog.pause = true
    // fnLog.childrenPaused = true

    fnLog.log('query:', query)
    fnLog.log('item:', item)

    const res = getTriggerOrActionListPageParams(query)
    fnLog.log('res:', res)

    switch (query.type) {
        case ActionOrTriggerListTypeEnum.addAction:
            fnLog.log('addAction 分支')
            const action = actionShowFloatWindowUtils.createDefaultData()
            fnLog.log('创建action:', action)

            if (!query.projectUlid) {
                fnLog.log('projectUlid不存在')
                return throwTraceError('projectUlid is not found', query)
            }

            const url = getNodeReaderUrl(query.projectUlid)
            fnLog.log('获取到URL:', url)

            if (!action.javaData.windowConf.htmlConf) {
                fnLog.log('htmlConf不存在, 创建htmlConf')
                action.javaData.windowConf.htmlConf = {
                    url: '',
                    webViewJsParams: {
                        fitContentWidth: 0,
                        fitContentHeight: 0,
                        javaToJsDataString: '',
                        fitContentClass: ''
                    },
                    webViewConf: {
                        backgroundColor: 0
                    },
                    jsBridgeName: 'android',
                    webViewJsName: 'AutoWebViewJs',
                    html: ''
                }
            } else {
                fnLog.log('htmlConf已存在')
            }

            action.javaData.windowConf.htmlConf.url = url
            fnLog.log('设置URL完成')

            if (!action.javaData.windowConf.htmlConf.webViewJsParams) {
                fnLog.log('webViewJsParams不存在, 创建webViewJsParams')
                action.javaData.windowConf.htmlConf.webViewJsParams = {
                    fitContentWidth: 0,
                    fitContentHeight: 0,
                    javaToJsDataString: '',
                    fitContentClass: ''
                }
            } else {
                fnLog.log('webViewJsParams已存在')
            }

            action.javaData.windowConf.htmlConf.webViewJsParams.fitContentClass = 'webviewMeatureContainer'
            fnLog.log('设置fitContentClass完成')

            fnLog.log('最终action数据:', JSON.stringify(action))

            if (!res.data.actionGroup) {
                fnLog.log('actionGroup 不存在')
                return throwTraceError('actionGroup is not found', query)
            }

            fnLog.log('分发编辑事件')
            projectEventUtils.dispatchEditEvent(projectEventUtils.EditType.add, {
                projectMemberType: ProjectMemberType.actionGroup,
                data: action,
                projectInfo: res.data
            })
            fnLog.log('事件已分发')

            fnLog.log('返回上一页')
            window.history.back()
            break
        case ActionOrTriggerListTypeEnum.updateAction:
            fnLog.log('updateAction 暂未实现')
            break
    }
}
